; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpcfw (Amstrad CPC - firmware text and keys), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 255		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs

ntc_start:
			di
			call ntc_rj_find		; Library: ROM - find the ROM, patch the jump block
			jr nc, ntc_rj_ok
			ei
			ret				; no ROM (the message is shown): back to the caller
ntc_rj_ok:
			ld hl, ntc_rj_exit
			push hl			; End comes back here: the caller's ROM selection again
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			; Option Class Interrupt: the classes' Tick subs, run at safe points (normal mode)
			ld hl, 300		; clock: every 300 interrupts
			ld (ntc_isl + 2), hl
			ld hl, 301			; the first after one period (+ the slot, so they take turns)
			ld (ntc_isl + 0), hl
			ld hl, p_clock_tick_c
			ld (ntc_isl + 6), hl
			ld hl, 0		; star: every frame
			ld (ntc_isl + 10), hl
			ld hl, 2			; the first after one period (+ the slot, so they take turns)
			ld (ntc_isl + 8), hl
			ld hl, p_star_tick_c
			ld (ntc_isl + 14), hl
			ld a, 2
			ld (ntc_isln), a
			ld hl, ntc_isl_tick
			ld (ntc_irqv), hl		; the interrupt handler counts for them
			ld ix, ntc_go
			jp ntc_plat_irqon		; interrupt handler for normal mode
ntc_go:
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:

			; Main.bas 7: Cls
			dw kw_cls

			; Main.bas 8: Locate 1, 3 : Print "Clock: a Tick once a second"
			dw kw_locatell, 1, 3
			dw kw_printstrvar, str0
			dw kw_printnl

			; Main.bas 9: Locate 1, 4 : Print "Star: a Tick every frame (50 a second)"
			dw kw_locatell, 1, 4
			dw kw_printstrvar, str1
			dw kw_printnl

			; Main.bas 10: Locate 1, 8 : Print "Press a key to stop"
			dw kw_locatell, 1, 8
			dw kw_printstrvar, str2
			dw kw_printnl

			; Main.bas 11: Do While Inkey <> 0 : Loop
do1_t:
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do1_e
			dw do1_t_go
do1_e:

			; Main.bas 12: Do
do2_t:

			; Main.bas 13: loops = loops + 1
			dw kw_l_add, var_loops, llit_1, var_loops

			; Main.bas 14: Locate 1, 6 : Print "Main loop: "; loops;
			dw kw_locatell, 1, 6
			dw kw_printstrvar, str3
			dw kw_l_print, var_loops

			; Main.bas 15: Loop Until Inkey <> 0
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do2_t
do2_e:

			; Main.bas 16: Locate 1, 10
			dw kw_locatell, 1, 10

			; Main.bas 17: Print "Clock ticked "; Clock.Seconds; " times, the star "; Star.Moves
			dw kw_printstrvar, str4
			dw kw_printint, var_clock_seconds
			dw kw_printstrvar, str5
			dw kw_printint, var_star_moves
			dw kw_printnl

			; Main.bas 18: End
			dw kw_stop

; ============================================================
; sub tick (normal mode)
; ============================================================

p_clock_tick:

			; Clock.cls 5: Seconds = Seconds + 1
			dw kw_inc, var_clock_seconds

			; Clock.cls 6: Locate 30, 3 : Print Seconds; "s ";
			dw kw_locatell, 30, 3
			dw kw_printint, var_clock_seconds
			dw kw_printstrvar, str6
			dw p_clock_tick_r

; ============================================================
; sub tick (normal mode)
; ============================================================

p_star_tick:

			; Star.cls 6: Locate x + 1, 1 : Print " ";
			dw kw_addl, var_star_x, 1, tmp2
			dw kw_ltov, 1, tmp3
			dw kw_locatevv, tmp2, tmp3
			dw kw_printstrvar, str7

			; Star.cls 7: x = (x + 1) Mod 39
			dw kw_addl, var_star_x, 1, tmp2
			dw kw_modvl, tmp2, 39, var_star_x

			; Star.cls 8: Locate x + 1, 1 : Print "*";
			dw kw_addl, var_star_x, 1, tmp2
			dw kw_ltov, 1, tmp3
			dw kw_locatevv, tmp2, tmp3
			dw kw_printstrvar, str8

			; Star.cls 9: Moves = Moves + 1
			dw kw_inc, var_star_moves
			dw p_star_tick_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

do1_t_go:			ld sp, do1_t
			jp ntc_xn

p_clock_tick_c:		; call tick (normal)
			ld (p_clock_tick_rs), sp
			ld sp, p_clock_tick
			jp ntc_xn
p_clock_tick_r:		; end of tick
			xor a			; Tick done: it may run again
			ld (ntc_isl + 4), a
			ld sp, (p_clock_tick_rs)
			jp ntc_xn
p_star_tick_c:		; call tick (normal)
			ld (p_star_tick_rs), sp
			ld sp, p_star_tick
			jp ntc_xn
p_star_tick_r:		; end of tick
			xor a			; Tick done: it may run again
			ld (ntc_isl + 12), a
			ld sp, (p_star_tick_rs)
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

var_loops:			dw 0, 0
var_clock_seconds:			dw 0
var_star_moves:			dw 0
p_clock_tick_rs:			dw 0
p_star_tick_rs:			dw 0
var_star_x:			dw 0
tmp0:			dw 0
tmp1:			dw 0
tmp2:			dw 0
tmp3:			dw 0

; numbers passed by address (read only)
llit_1:			dw 1, 0

; ============================================================
; Strings
; ============================================================

str0:			db "Clock: a Tick once a second", 0
str1:			db "Star: a Tick every frame (50 a second)", 0
str2:			db "Press a key to stop", 0
str3:			db "Main loop: ", 0
str4:			db "Clock ticked ", 0
str5:			db " times, the star ", 0
str6:			db "s ", 0
str7:			db " ", 0
str8:			db "*", 0

; ============================================================
; Keyword library (rom)
; ============================================================

; Library: ROM - the keyword library is in the NTC LIBRARY ROM (NTCFW.ROM).
; Its routines: this jump block, the numbers made into addresses by the ROM at the start.
; Its variables and constants: fixed addresses (RAM #8800 - #A5EF is the ROM's).
ntc_rj_block:
kw_stop:		jp 1
ntc_xn:		jp 2
kw_goto_iffalse_n:	jp 11
kw_ltov:		jp 47
kw_inc:		jp 51
kw_addl:		jp 54
kw_modvl:	jp 67
kw_cpnevl:	jp 98
kw_printstrvar:	jp 129
kw_printint:	jp 131
kw_printnl:	jp 138
kw_inkey:	jp 144
kw_cls:		jp 147
kw_locatell:	jp 148
kw_locatevv:	jp 149
kw_l_add:	jp 209
kw_l_print:	jp 233
ntc_isl_tick:	jp 287
ntc_plat_irqon:	jp 314
NTC_RJ_N	equ 19		; entries
ntc_csp	equ #8800		; ROM data
ntc_irqv	equ #883A		; ROM data
ntc_isl	equ #9778		; ROM bss
ntc_isln	equ #8834		; ROM data
ntc_nmode	equ #8806		; ROM data
ntc_v_free	equ #8844		; ROM data
ntc_v_romen	equ #884A		; ROM data
ntc_v_romold	equ #884C		; ROM data
ntc_v_stamp	equ #8848		; ROM data
ntc_v_start	equ #8846		; ROM data
			ASSERT ntc_free <= #8800, "Library: ROM - the program and its arrays must end below #8800 (the ROM's RAM)"

; the start: find the ROM in slots 0 - 31, have it patch the jump block. NC = ready;
; C = not there / too old (the message is shown, the caller's ROM selection is back)
ntc_rj_find:
			ld c, 0
			call #B90F		; KL ROM SELECT: B / C = the caller's state and selection
			ld (ntc_rj_old), bc
			ld c, 0
ntc_rj_next:
			push bc
			call #B90F		; KL ROM SELECT: ROM C
			pop bc
			ld a, (#C000)
			cp 1				; a background ROM?
			jr nz, ntc_rj_skip
			ld hl, (#C004)		; its names
			ld a, h
			cp #C0
			jr c, ntc_rj_skip
ntc_rj_name:
			ld a, (hl)
			inc hl
			or a
			jr nz, ntc_rj_name		; to the 0 after the names
			ld de, ntc_rj_sig
			ld b, ntc_rj_sige - ntc_rj_sig
ntc_rj_cmp:
			ld a, (de)
			cp (hl)
			jr nz, ntc_rj_skip
			inc de
			inc hl
			djnz ntc_rj_cmp
			ld e, (hl)
			inc hl
			ld d, (hl)			; its patcher
			ld (ntc_rj_call + 1), de
			ld a, c				; its slot
			ld hl, ntc_rj_block
			ld bc, NTC_RJ_N
ntc_rj_call:
			call 0				; HL = jump block, BC = entries, A = slot; C: DE = a number it hasn't got
			jr c, ntc_rj_lacks
			ld hl, ntc_free
			ld (ntc_v_free), hl
			ld hl, ntc_start
			ld (ntc_v_start), hl
			ld hl, 0
			ld (ntc_v_stamp), hl
			ld a, 0
			ld (ntc_v_romen), a
			ld a, (ntc_rj_old)
			ld (ntc_v_romold), a
			or a				; NC: ready
			ret
ntc_rj_skip:
			inc c
			ld a, c
			cp 32
			jr c, ntc_rj_next
			ld hl, ntc_rj_tnf
			jr ntc_rj_fail
ntc_rj_lacks:
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tlk
ntc_rj_fail:
			push hl
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT: the caller's selection again
			pop hl
			call ntc_rj_puts
			ld hl, ntc_rj_tlk
			or a
			sbc hl, de			; (DE: past the message shown)
			jr nz, ntc_rj_nl
			ld a, (ntc_rj_num + 1)
			call ntc_rj_hex
			ld a, (ntc_rj_num)
			call ntc_rj_hex
ntc_rj_nl:
			ld hl, ntc_rj_tnl
			call ntc_rj_puts
			ei
			call #BB06		; KM WAIT CHAR: a key first (a RUN" program's return resets the machine)
			di
			scf
			ret
ntc_rj_puts:				; HL = text, 0 ends; DE = its start
			ld d, h
			ld e, l
ntc_rj_pl:
			ld a, (hl)
			or a
			ret z
			call #BB5A		; TXT OUTPUT
			inc hl
			jr ntc_rj_pl
ntc_rj_hex:
			push af
			rrca
			rrca
			rrca
			rrca
			call ntc_rj_dig
			pop af
ntc_rj_dig:
			and 15
			add a, #90
			daa
			adc a, #40
			daa
			jp #BB5A
; End: the caller's ROM selection again, then back to the caller
ntc_rj_exit:
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT
			ret
ntc_rj_old:		dw 0			; the caller's ROM selection (C) and state (B)
ntc_rj_num:		dw 0
ntc_rj_sig:		db "NTC", 1, "CPCFW", 0	; the ROM's NTC block
ntc_rj_sige:
ntc_rj_tnf:		db "NTC LIBRARY ROM (CPCFW) not found", 0
ntc_rj_tlk:		db "NTC LIBRARY ROM too old: no routine #", 0
ntc_rj_tnl:		db 13, 10, "Press a key", 13, 10, 0

ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bss		equ ntc_end
ntc_bss_size	equ 0
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
			SAVEAMSDOS "E24.BIN", ntc_start, ntc_end - ntc_start, ntc_start